/* GhostWriter UI 0.4.0 – gebaut aus templates/*.html mit build.py, nicht von Hand ändern */
(function(){
  var VERSION="0.4.0";
  var T={};
  T["abschnitt-anlegen"]={html:"<h2 class=\"sr-only\">Formular zum Anlegen eines neuen Abschnitts in Kapitel {{CHAPTER_NUMBER}}: Titel, Ziel, Kurzbeschreibung, Faktencheck und Position.</h2>\n<style>\n.gw-f label{display:block;font-size:13px;font-weight:500;color:var(--text-primary);margin-bottom:4px}\n.gw-f .hint{font-size:12px;color:var(--text-muted);font-weight:400}\n.gw-f input,.gw-f textarea,.gw-f select{width:100%;box-sizing:border-box;padding:9px 12px;border:0.5px solid var(--border-strong);border-radius:var(--radius);background:var(--surface-2);color:var(--text-primary);font:inherit;font-size:14px}\n.gw-f input:focus,.gw-f textarea:focus,.gw-f select:focus{outline:none;border-color:var(--border-accent)}\n.gw-f textarea{resize:vertical;line-height:1.6}\n.gw-err{font-size:13px;color:var(--text-danger);margin-top:4px}\n.gw-btn{padding:9px 16px;border-radius:var(--radius);font:inherit;font-size:14px;font-weight:500;cursor:pointer}\n</style>\n<div style=\"padding:1rem 0\">\n  <form class=\"gw-f\" id=\"gw-abschnitt-anlegen\" data-chapter=\"{{CHAPTER_ID}}\" data-num=\"{{CHAPTER_NUMBER}}\" data-fc=\"{{FACT_CHECK_DEFAULT}}\" novalidate style=\"border:0.5px solid var(--border);border-radius:16px;background:var(--surface-1);padding:var(--pad-lg);display:flex;flex-direction:column;gap:var(--gap-md)\">\n    <div style=\"display:flex;align-items:center;gap:var(--gap-sm)\">\n      <i class=\"ti ti-plus\" style=\"font-size:18px;color:var(--text-secondary)\" aria-hidden=\"true\"></i>\n      <span style=\"font-size:16px;font-weight:500\">Neuer Abschnitt in Kapitel {{CHAPTER_NUMBER}}</span>\n      <span style=\"font-size:13px;color:var(--text-secondary);margin-left:auto\">{{CHAPTER_TITLE}}</span>\n    </div>\n    <div>\n      <label for=\"gw-title\">Titel</label>\n      <input id=\"gw-title\" placeholder=\"Titel des Abschnitts\">\n      <div class=\"gw-err\" id=\"gw-title-err\" hidden>Bitte einen Titel eingeben.</div>\n    </div>\n    <div>\n      <label for=\"gw-goal\">Ziel des Abschnitts <span class=\"hint\">was soll dieser Abschnitt leisten?</span></label>\n      <textarea id=\"gw-goal\" rows=\"2\"></textarea>\n    </div>\n    <div>\n      <label for=\"gw-summary\">Kurzbeschreibung <span class=\"hint\">worum es geht</span></label>\n      <textarea id=\"gw-summary\" rows=\"2\"></textarea>\n    </div>\n    <div style=\"display:flex;gap:var(--gap-md);flex-wrap:wrap\">\n      <div style=\"flex:1 1 160px\">\n        <label for=\"gw-fc\">Faktencheck</label>\n        <select id=\"gw-fc\">\n          <option value=\"disabled\">aus</option>\n          <option value=\"optional\">optional</option>\n          <option value=\"requested\">angefordert</option>\n        </select>\n      </div>\n      <div style=\"flex:2 1 240px\">\n        <label for=\"gw-pos\">Position</label>\n        <select id=\"gw-pos\">\n          {{#POSITIONS}}\n          <option {{POSITION_SELECTED}}>{{POSITION_LABEL}}</option>\n          {{/POSITIONS}}\n        </select>\n      </div>\n    </div>\n    <div style=\"display:flex;justify-content:flex-end;gap:var(--gap-sm);border-top:0.5px solid var(--border);padding-top:var(--pad-md)\">\n      <button type=\"button\" class=\"gw-btn\" id=\"gw-cancel\" style=\"border:0.5px solid var(--border-strong);background:transparent;color:var(--text-primary)\">Abbrechen</button>\n      <button type=\"button\" class=\"gw-btn\" id=\"gw-save\" style=\"border:0.5px solid var(--border-accent);background:var(--bg-accent);color:var(--text-accent)\">Abschnitt anlegen</button>\n    </div>\n  </form>\n</div>\n",run:function(){
function gwSend(text,action,data){var p=Object.assign({action:action},data||{});sendPrompt(text+'\n\n```gw\n'+JSON.stringify(p)+'\n```');}
(function(){
  var f=document.getElementById('gw-abschnitt-anlegen');
  var $=function(id){return document.getElementById(id);};
  var id=f.dataset.chapter,num=f.dataset.num;
  if(f.dataset.fc)$('gw-fc').value=f.dataset.fc;
  var title=$('gw-title'),err=$('gw-title-err');
  title.addEventListener('input',function(){err.hidden=true;});
  function lock(){f.querySelectorAll('input,textarea,select,button').forEach(function(x){x.disabled=true;});f.style.opacity='0.6';}
  $('gw-save').addEventListener('click',function(){
    if(!title.value.trim()){err.hidden=false;title.focus();return;}
    var g=function(k){return $(k).value.trim();},s=$('gw-pos');
    var d={chapter_id:id,title:g('gw-title'),goal:g('gw-goal'),summary:g('gw-summary'),fact_check:$('gw-fc').value,position:s.selectedIndex,position_label:s.value};
    lock();
    gwSend('Neuer Abschnitt in Kapitel '+num+': '+d.title,'section.create',d);
  });
  $('gw-cancel').addEventListener('click',function(){lock();gwSend('Neuer Abschnitt in Kapitel '+num+' abgebrochen','form.cancel',{form:'section.create',chapter_id:id});});
})();

}};
  T["abschnitt-bearbeiten"]={html:"<h2 class=\"sr-only\">Abschnitt {{SECTION_NUMBER}} „{{SECTION_TITLE}}“ bearbeiten: Ziel, Kurzbeschreibung, offene Marker, Manuskript, Faktencheck, Freigaben und Abschnittssteuerung.</h2>\n<style>\n.gw-sq{width:40px;height:40px;flex:none;border:0.5px solid var(--border);border-radius:12px;background:var(--surface-2);display:flex;align-items:center;justify-content:center;font-size:20px;color:var(--text-secondary);cursor:pointer;padding:0}\n.gw-sq:hover:not(:disabled){border-color:var(--border-strong);color:var(--text-primary)}\n.gw-sq:disabled{opacity:0.35;cursor:default}\n.gw-sq.on{border-color:var(--border-warning);background:var(--bg-warning);color:var(--text-warning)}\n.gw-lbl{display:block;font-size:13px;font-weight:500;margin-bottom:4px}\n.gw-hint{font-size:12px;color:var(--text-muted);font-weight:400}\n.gw-in{width:100%;box-sizing:border-box;padding:9px 12px;border:0.5px solid var(--border-strong);border-radius:var(--radius);background:var(--surface-2);color:var(--text-primary);font:inherit;font-size:14px;line-height:1.6;resize:vertical}\n.gw-in:focus{outline:none;border-color:var(--border-accent)}\n.gw-mk{display:flex;align-items:flex-start;gap:var(--gap-sm);padding:8px 10px;border-radius:var(--radius);font-size:13px;line-height:1.5;border:0.5px solid var(--border);background:var(--surface-2);color:var(--text-secondary)}\n.gw-mk-quelle{border-color:var(--border-warning);background:var(--bg-warning);color:var(--text-warning)}\n.gw-mk-medizin{border-color:var(--border-danger);background:var(--bg-danger);color:var(--text-danger)}\n.gw-mk-recht{border-color:var(--border-accent);background:var(--bg-accent);color:var(--text-accent)}\n.gw-mk-label{font-weight:500}\n.gw-mk-anekdote .gw-mk-label{color:var(--text-primary)}\n.gw-opt{display:flex;align-items:center;gap:var(--gap-sm);text-align:left;padding:10px 12px;border:0.5px solid var(--border-strong);border-radius:var(--radius);background:var(--surface-2);color:var(--text-primary);cursor:pointer;font:inherit;width:100%}\n.gw-opt:hover:not(:disabled){border-color:var(--border-stronger)}\n.gw-opt.sel{border-color:var(--border-accent);background:var(--bg-accent)}\n.gw-card{border:0.5px solid var(--border);border-radius:12px;background:var(--surface-2);padding:var(--pad-md);display:flex;flex-direction:column;gap:var(--gap-sm);min-width:0}\n.gw-ico{width:36px;height:36px;flex:none;border:0.5px solid var(--border);border-radius:10px;background:var(--surface-1);display:flex;align-items:center;justify-content:center;font-size:18px;color:var(--text-secondary)}\n.gw-chk{display:flex;align-items:center;gap:8px;font-size:14px;cursor:pointer}\n.gw-btn{padding:9px 16px;border-radius:var(--radius);font:inherit;font-size:14px;font-weight:500;cursor:pointer}\n.gw-wrap.locked .gw-lockable{opacity:0.5;pointer-events:none}\n@media (max-width:560px){.gw-two{grid-template-columns:1fr!important}}\n.gw-opt[data-available=\"false\"]{opacity:0.45;cursor:default}\n.gw-later{font-size:11px;color:var(--text-muted);margin-left:auto;white-space:nowrap}\n</style>\n<div style=\"padding:1rem 0\">\n  <div class=\"gw-wrap\" id=\"gw-abschnitt\" data-section-id=\"{{SECTION_ID}}\" data-section-number=\"{{SECTION_NUMBER}}\" data-section-title=\"{{SECTION_TITLE}}\" data-fact-check=\"{{FACT_CHECK}}\" data-approval-writing=\"{{APPROVAL_WRITING}}\" data-approval-section=\"{{APPROVAL_SECTION}}\" data-chapter-id=\"{{CHAPTER_ID}}\" data-prev=\"{{PREV_SECTION_PROMPT}}\" data-prev-id=\"{{PREV_SECTION_ID}}\" data-next=\"{{NEXT_SECTION_PROMPT}}\" data-next-id=\"{{NEXT_SECTION_ID}}\" style=\"border:0.5px solid var(--border);border-radius:16px;background:var(--surface-1);padding:var(--pad-lg);display:flex;flex-direction:column;gap:var(--gap-md)\">\n    <div>\n      <div style=\"display:flex;align-items:flex-start;gap:var(--gap-md);flex-wrap:wrap-reverse\">\n        <div style=\"flex:1;min-width:220px\">\n          <div style=\"display:flex;align-items:center;gap:var(--gap-sm);flex-wrap:wrap;margin-bottom:4px\">\n            <span style=\"font-size:12px;font-weight:500;padding:2px 8px;border-radius:999px;border:0.5px solid var(--border-accent);background:var(--bg-accent);color:var(--text-accent)\">{{PROJECT_TITLE_SHORT}}</span>\n            <span style=\"font-size:12px;color:var(--text-muted)\">Kapitel {{CHAPTER_NUMBER}} · Abschnitt {{SECTION_NUMBER}}</span>\n          </div>\n          <div style=\"font-size:20px;font-weight:500;line-height:1.3\">{{SECTION_TITLE}}</div>\n        </div>\n        <div style=\"display:flex;gap:var(--gap-sm);margin-left:auto\">\n          <button type=\"button\" class=\"gw-sq\" data-p=\"Zurück zu Kapitel {{CHAPTER_NUMBER}}\" data-a=\"view.chapter\" data-args='{\"chapter_id\":\"{{CHAPTER_ID}}\"}' title=\"Zum Kapitel\" aria-label=\"Zum Kapitel\"><i class=\"ti ti-arrow-up\" aria-hidden=\"true\"></i></button>\n          <button type=\"button\" class=\"gw-sq\" id=\"gw-prev\" title=\"Vorheriger Abschnitt\" aria-label=\"Vorheriger Abschnitt\"><i class=\"ti ti-chevron-left\" aria-hidden=\"true\"></i></button>\n          <button type=\"button\" class=\"gw-sq\" id=\"gw-next\" title=\"Nächster Abschnitt\" aria-label=\"Nächster Abschnitt\"><i class=\"ti ti-chevron-right\" aria-hidden=\"true\"></i></button>\n          <button type=\"button\" class=\"gw-sq\" id=\"gw-lock\" aria-pressed=\"false\" title=\"Abschnitt sperren\" aria-label=\"Abschnitt sperren\"><i class=\"ti ti-lock-open\" aria-hidden=\"true\"></i></button>\n        </div>\n      </div>\n      <div style=\"display:flex;align-items:center;justify-content:space-between;gap:var(--gap-md);flex-wrap:wrap;margin-top:8px\">\n        <div style=\"font-size:14px;color:var(--text-secondary);display:flex;align-items:center;gap:var(--gap-md);flex-wrap:wrap\">\n          <span style=\"display:flex;align-items:center;gap:6px\"><i class=\"ti ti-progress\" aria-hidden=\"true\"></i>{{SECTION_STATUS}}</span>\n          <span style=\"display:flex;align-items:center;gap:6px\"><i class=\"ti ti-alert-triangle\" aria-hidden=\"true\"></i>{{MARKER_COUNT_TEXT}}</span>\n        </div>\n        <div style=\"font-size:14px;color:var(--text-secondary);display:flex;align-items:center;gap:6px;margin-left:auto\" title=\"{{SECTION_COST_HINT}}\"><i class=\"ti ti-coins\" aria-hidden=\"true\"></i><span style=\"font-variant-numeric:tabular-nums\">{{SECTION_COST}}</span></div>\n      </div>\n    </div>\n\n    <div class=\"gw-lockable\" style=\"display:flex;flex-direction:column;gap:var(--gap-md)\">\n      <div class=\"gw-two\" style=\"display:grid;grid-template-columns:1fr 1fr;gap:var(--gap-md);border-top:0.5px solid var(--border);padding-top:var(--pad-md)\">\n        <div>\n          <label class=\"gw-lbl\" for=\"gw-goal\">Ziel des Abschnitts</label>\n          <textarea class=\"gw-in\" id=\"gw-goal\" rows=\"3\">{{SECTION_GOAL}}</textarea>\n        </div>\n        <div>\n          <label class=\"gw-lbl\" for=\"gw-summary\">Kurzbeschreibung</label>\n          <textarea class=\"gw-in\" id=\"gw-summary\" rows=\"3\">{{SECTION_SUMMARY}}</textarea>\n        </div>\n      </div>\n\n      <div data-gw-if=\"MARKERS\" style=\"border-top:0.5px solid var(--border);padding-top:var(--pad-md)\">\n        <div class=\"gw-lbl\">Offene Marker</div>\n        <div style=\"display:flex;flex-direction:column;gap:var(--gap-xs)\">\n          {{#MARKERS}}\n          <div class=\"gw-mk gw-mk-{{MARKER_TYPE}}\"><i class=\"ti gw-mk-icon\" data-type=\"{{MARKER_TYPE}}\" style=\"font-size:16px;margin-top:2px\" aria-hidden=\"true\"></i><span style=\"flex:1\"><span class=\"gw-mk-label\">{{MARKER_LABEL}}</span> · {{MARKER_TEXT}}</span></div>\n          {{/MARKERS}}\n        </div>\n      </div>\n\n      <div style=\"border-top:0.5px solid var(--border);padding-top:var(--pad-md)\">\n        <label class=\"gw-lbl\" for=\"gw-ms\">Manuskript <span class=\"gw-hint\">Markdown</span></label>\n        <textarea class=\"gw-in\" id=\"gw-ms\" rows=\"14\" style=\"font-family:var(--font-mono);font-size:13px\">{{SECTION_MANUSCRIPT}}</textarea>\n      </div>\n\n      <div class=\"gw-two\" style=\"display:grid;grid-template-columns:1fr 1fr;gap:var(--gap-md);border-top:0.5px solid var(--border);padding-top:var(--pad-md)\">\n        <div>\n          <label class=\"gw-lbl\" for=\"gw-fc\">Faktencheck</label>\n          <select id=\"gw-fc\" class=\"gw-in\" style=\"width:auto;padding:6px 10px\">\n            <option value=\"disabled\">aus</option>\n            <option value=\"optional\">optional</option>\n            <option value=\"requested\">angefordert</option>\n          </select>\n        </div>\n        <div>\n          <div class=\"gw-lbl\">Freigaben</div>\n          <label class=\"gw-chk\"><input type=\"checkbox\" id=\"gw-apw\"> Schreiben freigegeben</label>\n          <label class=\"gw-chk\" style=\"margin-top:6px\"><input type=\"checkbox\" id=\"gw-aps\"> Abschnitt freigegeben</label>\n        </div>\n      </div>\n\n      <div style=\"border-top:0.5px solid var(--border);padding-top:var(--pad-md)\">\n        <div class=\"gw-lbl\">Abschnittssteuerung</div>\n        <div class=\"gw-two\" style=\"display:grid;grid-template-columns:1fr 1fr;gap:var(--gap-sm)\">\n          <div class=\"gw-card\" data-task=\"Recherche\">\n            <div style=\"display:flex;align-items:center;gap:var(--gap-sm)\"><div class=\"gw-ico\"><i class=\"ti ti-search\" aria-hidden=\"true\"></i></div><div><div style=\"font-size:14px;font-weight:500\">Recherche</div><div style=\"font-size:12px;color:var(--text-secondary)\">Quellen finden und auswerten</div></div></div>\n            <button type=\"button\" class=\"gw-opt\" data-mode=\"zeitgesteuert\" data-available=\"false\"><i class=\"ti ti-clock\" style=\"font-size:16px;color:var(--text-secondary)\" aria-hidden=\"true\"></i><span style=\"font-size:13px\"><span style=\"font-weight:500\">Zeitgesteuert</span> · Cloud-Warteschlange</span></button>\n            <button type=\"button\" class=\"gw-opt\" data-mode=\"sofort\"><i class=\"ti ti-bolt\" style=\"font-size:16px;color:var(--text-secondary)\" aria-hidden=\"true\"></i><span style=\"font-size:13px\"><span style=\"font-weight:500\">Sofort</span> · hier im Chat</span></button>\n          </div>\n          <div class=\"gw-card\" data-task=\"Ghostwriting\">\n            <div style=\"display:flex;align-items:center;gap:var(--gap-sm)\"><div class=\"gw-ico\"><i class=\"ti ti-feather\" aria-hidden=\"true\"></i></div><div><div style=\"font-size:14px;font-weight:500\">Ghostwriting</div><div style=\"font-size:12px;color:var(--text-secondary)\">Automated Content Generation</div></div></div>\n            <button type=\"button\" class=\"gw-opt\" data-mode=\"zeitgesteuert\" data-available=\"false\"><i class=\"ti ti-clock\" style=\"font-size:16px;color:var(--text-secondary)\" aria-hidden=\"true\"></i><span style=\"font-size:13px\"><span style=\"font-weight:500\">Zeitgesteuert</span> · Cloud-Warteschlange</span></button>\n            <button type=\"button\" class=\"gw-opt\" data-mode=\"sofort\"><i class=\"ti ti-bolt\" style=\"font-size:16px;color:var(--text-secondary)\" aria-hidden=\"true\"></i><span style=\"font-size:13px\"><span style=\"font-weight:500\">Sofort</span> · hier im Chat</span></button>\n          </div>\n        </div>\n      </div>\n\n      <div style=\"display:flex;justify-content:flex-end;gap:var(--gap-sm);border-top:0.5px solid var(--border);padding-top:var(--pad-md)\">\n        <button type=\"button\" class=\"gw-btn\" id=\"gw-cancel\" style=\"border:0.5px solid var(--border-strong);background:transparent;color:var(--text-primary)\">Verwerfen</button>\n        <button type=\"button\" class=\"gw-btn\" id=\"gw-save\" style=\"border:0.5px solid var(--border-accent);background:var(--bg-accent);color:var(--text-accent)\">Speichern</button>\n      </div>\n    </div>\n  </div>\n</div>\n",run:function(){
function gwSend(text,action,data){var p=Object.assign({action:action},data||{});sendPrompt(text+'\n\n```gw\n'+JSON.stringify(p)+'\n```');}
(function(){
  var wrap=document.getElementById('gw-abschnitt'),d=wrap.dataset;
  var ref='Abschnitt '+d.sectionNumber+' „'+d.sectionTitle+'“ (ID '+d.sectionId+')';
  var $=function(id){return document.getElementById(id);};

  var icons={anekdote:'ti-quote',quelle:'ti-book',medizin:'ti-stethoscope',recht:'ti-scale'};
  wrap.querySelectorAll('.gw-mk-icon').forEach(function(i){i.classList.add(icons[i.dataset.type]||'ti-alert-triangle');});

  $('gw-fc').value=d.factCheck||'optional';
  $('gw-apw').checked=d.approvalWriting==='true';
  $('gw-aps').checked=d.approvalSection==='true';

  [['gw-prev',d.prev,d.prevId],['gw-next',d.next,d.nextId]].forEach(function(p){
    var b=$(p[0]);
    if(!p[2]){b.disabled=true;return;}
    b.title=p[1];
    b.addEventListener('click',function(){gwSend(p[1],'view.section',{section_id:p[2]});});
  });
  wrap.querySelectorAll('.gw-sq[data-p]').forEach(function(b){b.addEventListener('click',function(){gwSend(b.dataset.p,b.dataset.a,b.dataset.args?JSON.parse(b.dataset.args):{});});});

  var texts={
    'Recherche|zeitgesteuert':'Recherche für '+ref+' zeitgesteuert als Job in die Cloud-Warteschlange übergeben',
    'Recherche|sofort':ref+' jetzt sofort hier im Chat recherchieren',
    'Ghostwriting|zeitgesteuert':'Ghostwriting für '+ref+' zeitgesteuert als Job in die Cloud-Warteschlange übergeben',
    'Ghostwriting|sofort':ref+' jetzt sofort hier im Chat schreiben (Ghostwriting)'
  };
  wrap.querySelectorAll('.gw-opt[data-available="false"]').forEach(function(x){
    x.disabled=true;x.title='Nicht verfügbar in v0.5';
    var s=document.createElement('span');s.className='gw-later';s.textContent='nach v0.5';x.appendChild(s);
  });
  wrap.querySelectorAll('.gw-card').forEach(function(card){
    var o=card.querySelectorAll('.gw-opt');
    o.forEach(function(b){b.addEventListener('click',function(){
      o.forEach(function(x){x.disabled=true;if(x===b)x.classList.add('sel');else x.style.opacity='0.45';});
      gwSend(texts[card.dataset.task+'|'+b.dataset.mode],'run.start',{section_id:d.sectionId,task:card.dataset.task==='Recherche'?'research':'writing',mode:b.dataset.mode==='sofort'?'immediate':'scheduled'});
    });});
  });

  var lock=$('gw-lock'),locked=false;
  lock.addEventListener('click',function(){
    locked=!locked;
    wrap.classList.toggle('locked',locked);
    lock.classList.toggle('on',locked);
    lock.setAttribute('aria-pressed',String(locked));
    var l=locked?'Abschnitt entsperren':'Abschnitt sperren';
    lock.title=l;lock.setAttribute('aria-label',l);
    lock.querySelector('i').className=locked?'ti ti-lock':'ti ti-lock-open';
  });

  function done(){wrap.querySelectorAll('.gw-lockable input,.gw-lockable textarea,.gw-lockable select,.gw-lockable button').forEach(function(x){x.disabled=true;});}
  var fcText={disabled:'aus',optional:'optional',requested:'angefordert'};
  $('gw-save').addEventListener('click',function(){
    var data={section_id:d.sectionId,goal:$('gw-goal').value.trim(),summary:$('gw-summary').value.trim(),
      fact_check:$('gw-fc').value,approvals:{writing:$('gw-apw').checked,section:$('gw-aps').checked},
      manuscript:$('gw-ms').value};
    done();gwSend(ref+' speichern (Faktencheck: '+fcText[data.fact_check]+')','section.update',data);
  });
  $('gw-cancel').addEventListener('click',function(){done();gwSend('Änderungen an '+ref+' verworfen','form.cancel',{form:'section.update',section_id:d.sectionId});});
})();

}};
  T["abschnittssteuerung"]={html:"<h2 class=\"sr-only\">Abschnittssteuerung für Abschnitt {{SECTION_NUMBER}} {{SECTION_TITLE}}: Recherche und Ghostwriting zeitgesteuert oder sofort ausführen, Abschnitt sperren oder entsperren.</h2>\n<style>\n.gw-wrap{display:grid;grid-template-columns:1fr 1fr 56px;gap:var(--gap-md);padding:1rem 0}\n.gw-card{border:0.5px solid var(--border);border-radius:16px;background:var(--surface-1);padding:var(--pad-md);display:flex;flex-direction:column;gap:var(--gap-sm);min-width:0}\n.gw-head{display:flex;align-items:center;gap:var(--gap-sm);margin-bottom:4px}\n.gw-ico{width:40px;height:40px;flex:none;border:0.5px solid var(--border);border-radius:12px;background:var(--surface-2);display:flex;align-items:center;justify-content:center;font-size:20px;color:var(--text-secondary)}\n.gw-opt{display:flex;align-items:center;gap:var(--gap-sm);text-align:left;padding:10px 12px;border:0.5px solid var(--border-strong);border-radius:var(--radius);background:var(--surface-2);color:var(--text-primary);cursor:pointer;font:inherit;width:100%}\n.gw-opt:hover:not(:disabled){border-color:var(--border-stronger)}\n.gw-opt:disabled{cursor:default}\n.gw-opt.sel{border-color:var(--border-accent);background:var(--bg-accent)}\n.gw-lockcard{border:0.5px solid var(--border);border-radius:16px;background:var(--surface-1);display:flex;align-items:flex-start;justify-content:center;padding:var(--pad-md) 0}\n.gw-lock{width:40px;height:40px;border:0.5px solid var(--border);border-radius:12px;background:var(--surface-2);color:var(--text-secondary);display:flex;align-items:center;justify-content:center;font-size:20px;cursor:pointer}\n.gw-lock:hover{border-color:var(--border-strong)}\n.gw-lock.on{border-color:var(--border-warning);background:var(--bg-warning);color:var(--text-warning)}\n.gw-wrap.locked .gw-card{opacity:0.5}\n@media (max-width:560px){.gw-wrap{grid-template-columns:1fr 56px}.gw-card[data-task=\"Ghostwriting\"]{grid-row:2}.gw-lockcard{grid-row:1/3;grid-column:2}}\n.gw-opt[data-available=\"false\"]{opacity:0.45;cursor:default}\n.gw-later{font-size:11px;color:var(--text-muted);margin-left:auto;white-space:nowrap}\n</style>\n<div class=\"gw-wrap\" id=\"gw-abschnittssteuerung\" data-section-id=\"{{SECTION_ID}}\" data-section-number=\"{{SECTION_NUMBER}}\" data-section-title=\"{{SECTION_TITLE}}\">\n  <div class=\"gw-card\" data-task=\"Recherche\">\n    <div class=\"gw-head\">\n      <div class=\"gw-ico\"><i class=\"ti ti-search\" aria-hidden=\"true\"></i></div>\n      <div><div style=\"font-size:16px;font-weight:500\">Recherche</div><div style=\"font-size:13px;color:var(--text-secondary)\">Quellen finden und auswerten</div></div>\n    </div>\n    <button type=\"button\" class=\"gw-opt\" data-mode=\"zeitgesteuert\" data-available=\"false\"><i class=\"ti ti-clock\" style=\"font-size:18px;color:var(--text-secondary)\" aria-hidden=\"true\"></i><span><span style=\"font-size:14px;font-weight:500\">Zeitgesteuert</span><br><span style=\"font-size:12px;color:var(--text-secondary)\">Job in der Cloud-Warteschlange</span></span></button>\n    <button type=\"button\" class=\"gw-opt\" data-mode=\"sofort\"><i class=\"ti ti-bolt\" style=\"font-size:18px;color:var(--text-secondary)\" aria-hidden=\"true\"></i><span><span style=\"font-size:14px;font-weight:500\">Sofort</span><br><span style=\"font-size:12px;color:var(--text-secondary)\">Direkt hier im Chat</span></span></button>\n  </div>\n  <div class=\"gw-card\" data-task=\"Ghostwriting\">\n    <div class=\"gw-head\">\n      <div class=\"gw-ico\"><i class=\"ti ti-feather\" aria-hidden=\"true\"></i></div>\n      <div><div style=\"font-size:16px;font-weight:500\">Ghostwriting</div><div style=\"font-size:13px;color:var(--text-secondary)\">Automated Content Generation (ACG)</div></div>\n    </div>\n    <button type=\"button\" class=\"gw-opt\" data-mode=\"zeitgesteuert\" data-available=\"false\"><i class=\"ti ti-clock\" style=\"font-size:18px;color:var(--text-secondary)\" aria-hidden=\"true\"></i><span><span style=\"font-size:14px;font-weight:500\">Zeitgesteuert</span><br><span style=\"font-size:12px;color:var(--text-secondary)\">Job in der Cloud-Warteschlange</span></span></button>\n    <button type=\"button\" class=\"gw-opt\" data-mode=\"sofort\"><i class=\"ti ti-bolt\" style=\"font-size:18px;color:var(--text-secondary)\" aria-hidden=\"true\"></i><span><span style=\"font-size:14px;font-weight:500\">Sofort</span><br><span style=\"font-size:12px;color:var(--text-secondary)\">Direkt hier im Chat</span></span></button>\n  </div>\n  <div class=\"gw-lockcard\">\n    <button type=\"button\" class=\"gw-lock\" aria-pressed=\"false\" aria-label=\"Abschnitt sperren\" title=\"Abschnitt sperren\"><i class=\"ti ti-lock-open\" aria-hidden=\"true\"></i></button>\n  </div>\n</div>\n",run:function(){
function gwSend(text,action,data){var p=Object.assign({action:action},data||{});sendPrompt(text+'\n\n```gw\n'+JSON.stringify(p)+'\n```');}
(function(){
  var wrap=document.getElementById('gw-abschnittssteuerung');
  var ref='Abschnitt '+wrap.dataset.sectionNumber+' „'+wrap.dataset.sectionTitle+'“ (ID '+wrap.dataset.sectionId+')';
  var texts={
    'Recherche|zeitgesteuert':'Recherche für '+ref+' zeitgesteuert als Job in die Cloud-Warteschlange übergeben',
    'Recherche|sofort':ref+' jetzt sofort hier im Chat recherchieren',
    'Ghostwriting|zeitgesteuert':'Ghostwriting für '+ref+' zeitgesteuert als Job in die Cloud-Warteschlange übergeben',
    'Ghostwriting|sofort':ref+' jetzt sofort hier im Chat schreiben (Ghostwriting)'
  };
  wrap.querySelectorAll('.gw-opt[data-available="false"]').forEach(function(x){
    x.disabled=true;x.title='Nicht verfügbar in v0.5';
    var s=document.createElement('span');s.className='gw-later';s.textContent='nach v0.5';x.appendChild(s);
  });
  var lock=wrap.querySelector('.gw-lock'),ico=lock.querySelector('i'),locked=false;
  function refresh(){
    wrap.querySelectorAll('.gw-card').forEach(function(card){
      var done=card.dataset.done==='1';
      card.querySelectorAll('.gw-opt').forEach(function(x){x.disabled=locked||done||x.dataset.available==='false';});
    });
  }
  wrap.querySelectorAll('.gw-card').forEach(function(card){
    var opts=card.querySelectorAll('.gw-opt');
    opts.forEach(function(b){
      b.addEventListener('click',function(){
        if(locked)return;
        card.dataset.done='1';
        opts.forEach(function(x){if(x===b){x.classList.add('sel');}else{x.style.opacity='0.45';}});
        refresh();
        gwSend(texts[card.dataset.task+'|'+b.dataset.mode],'run.start',{section_id:wrap.dataset.sectionId,task:card.dataset.task==='Recherche'?'research':'writing',mode:b.dataset.mode==='sofort'?'immediate':'scheduled'});
      });
    });
  });
  lock.addEventListener('click',function(){
    locked=!locked;
    wrap.classList.toggle('locked',locked);
    lock.classList.toggle('on',locked);
    lock.setAttribute('aria-pressed',String(locked));
    var lbl=locked?'Abschnitt entsperren':'Abschnitt sperren';
    lock.setAttribute('aria-label',lbl);lock.title=lbl;
    ico.className=locked?'ti ti-lock':'ti ti-lock-open';
    refresh();
  });
})();

}};
  T["auflage-erzeugen"]={html:"<h2 class=\"sr-only\">Formular zum Erzeugen von {{EDITION_NAME}}: Erscheinungsdatum und Anmerkungen.</h2>\n<style>\n.gw-f label{display:block;font-size:13px;font-weight:500;color:var(--text-primary);margin-bottom:4px}\n.gw-f .hint{font-size:12px;color:var(--text-muted);font-weight:400}\n.gw-f input,.gw-f textarea{width:100%;box-sizing:border-box;padding:9px 12px;border:0.5px solid var(--border-strong);border-radius:var(--radius);background:var(--surface-2);color:var(--text-primary);font:inherit;font-size:14px}\n.gw-f input:focus,.gw-f textarea:focus{outline:none;border-color:var(--border-accent)}\n.gw-f textarea{resize:vertical;line-height:1.6}\n.gw-err{font-size:13px;color:var(--text-danger);margin-top:4px}\n.gw-btn{padding:9px 16px;border-radius:var(--radius);font:inherit;font-size:14px;font-weight:500;cursor:pointer}\n.gw-key{font-size:13px;color:var(--text-muted)}\n.gw-ro{font-size:14px;color:var(--text-primary)}\n.gw-pill{font-size:12px;padding:2px 8px;border-radius:999px;border:0.5px solid var(--border);background:var(--surface-2);color:var(--text-secondary)}\n</style>\n<div style=\"padding:1rem 0\">\n  <form class=\"gw-f\" id=\"gw-auflage\" novalidate data-name=\"{{EDITION_NAME}}\" data-tag=\"{{EDITION_TAG}}\" style=\"border:0.5px solid var(--border);border-radius:16px;background:var(--surface-1);padding:var(--pad-lg);display:flex;flex-direction:column;gap:var(--gap-md)\">\n    <div style=\"display:flex;align-items:center;gap:var(--gap-sm)\">\n      <i class=\"ti ti-books\" style=\"font-size:18px;color:var(--text-secondary)\" aria-hidden=\"true\"></i>\n      <span style=\"font-size:16px;font-weight:500\">Neue Auflage erzeugen</span>\n    </div>\n\n    <div style=\"display:grid;grid-template-columns:auto 1fr;gap:6px var(--gap-md);align-items:baseline;padding:var(--pad-md);border:0.5px solid var(--border);border-radius:var(--radius);background:var(--surface-2)\">\n      <span class=\"gw-key\">Auflage</span><span class=\"gw-ro\" style=\"font-weight:500\">{{EDITION_NUMBER}}</span>\n      <span class=\"gw-key\">Name</span><span class=\"gw-ro\">{{EDITION_NAME}}</span>\n      <span class=\"gw-key\">Tag</span><span class=\"gw-ro\" style=\"font-family:var(--font-mono);font-size:13px\">{{EDITION_TAG}}</span>\n      <span class=\"gw-key\">Formate</span><span id=\"gw-formats\" style=\"display:flex;gap:6px;flex-wrap:wrap\">\n        {{#FORMATS}}\n        <span class=\"gw-pill\">{{FORMAT_LABEL}}</span>\n        {{/FORMATS}}\n      </span>\n    </div>\n\n    <div>\n      <label for=\"gw-date\">Erscheinungsdatum</label>\n      <input type=\"date\" id=\"gw-date\" value=\"{{EDITION_DATE_DEFAULT}}\" style=\"width:auto\">\n      <div class=\"gw-err\" id=\"gw-date-err\" hidden>Bitte ein Erscheinungsdatum wählen.</div>\n    </div>\n    <div>\n      <label for=\"gw-notes\">Anmerkungen <span class=\"hint\">optional, erscheinen in den Release Notes</span></label>\n      <textarea id=\"gw-notes\" rows=\"4\" placeholder=\"z. B. Was ist neu oder korrigiert gegenüber der vorigen Auflage?\"></textarea>\n    </div>\n\n    <div id=\"gw-warning\" style=\"display:flex;align-items:flex-start;gap:var(--gap-sm);padding:10px 12px;border:0.5px solid var(--border-warning);border-radius:var(--radius);background:var(--bg-warning);color:var(--text-warning);font-size:13px;line-height:1.5\">\n      <i class=\"ti ti-alert-triangle\" style=\"font-size:16px;margin-top:1px\" aria-hidden=\"true\"></i>\n      <span id=\"gw-warning-text\">{{APPROVAL_WARNING_TEXT}}</span>\n    </div>\n\n    <div style=\"display:flex;justify-content:flex-end;gap:var(--gap-sm);border-top:0.5px solid var(--border);padding-top:var(--pad-md)\">\n      <button type=\"button\" class=\"gw-btn\" id=\"gw-cancel\" style=\"border:0.5px solid var(--border-strong);background:transparent;color:var(--text-primary)\">Abbrechen</button>\n      <button type=\"button\" class=\"gw-btn\" id=\"gw-save\" style=\"border:0.5px solid var(--border-accent);background:var(--bg-accent);color:var(--text-accent)\">Erzeugen</button>\n    </div>\n  </form>\n</div>\n",run:function(){
function gwSend(text,action,data){var p=Object.assign({action:action},data||{});sendPrompt(text+'\n\n```gw\n'+JSON.stringify(p)+'\n```');}
(function(){
  var f=document.getElementById('gw-auflage');
  var $=function(id){return document.getElementById(id);};
  if(!$('gw-warning-text').textContent.trim())$('gw-warning').remove();
  var d=$('gw-date'),e=$('gw-date-err');
  d.addEventListener('input',function(){e.hidden=true;});
  function lock(){f.querySelectorAll('input,textarea,button').forEach(function(x){x.disabled=true;});f.style.opacity='0.6';}
  $('gw-save').addEventListener('click',function(){
    if(!d.value){e.hidden=false;d.focus();return;}
    var formats=[].map.call($('gw-formats').querySelectorAll('.gw-pill'),function(p){return p.textContent.trim();}).join(', ');
    var notes=$('gw-notes').value.trim()||'(keine – Release Notes aus den Änderungen seit der letzten Auflage zusammenstellen)';
    lock();
    gwSend('Neue Auflage erzeugen: '+f.dataset.name,'edition.create',{name:f.dataset.name,tag:f.dataset.tag,date:d.value,formats:formats.split(', '),notes:$('gw-notes').value.trim()});
  });
  $('gw-cancel').addEventListener('click',function(){lock();gwSend('Neue Auflage erzeugen abgebrochen','form.cancel',{form:'edition.create'});});
})();

}};
  T["kapitel-anlegen"]={html:"<h2 class=\"sr-only\">Formular zum Anlegen eines neuen Kapitels: Titel, Kurzbeschreibung, Ziel des Kapitels und Position.</h2>\n<style>\n.gw-f label{display:block;font-size:13px;font-weight:500;color:var(--text-primary);margin-bottom:4px}\n.gw-f .hint{font-size:12px;color:var(--text-muted);font-weight:400}\n.gw-f input,.gw-f textarea,.gw-f select{width:100%;box-sizing:border-box;padding:9px 12px;border:0.5px solid var(--border-strong);border-radius:var(--radius);background:var(--surface-2);color:var(--text-primary);font:inherit;font-size:14px}\n.gw-f input:focus,.gw-f textarea:focus,.gw-f select:focus{outline:none;border-color:var(--border-accent)}\n.gw-f textarea{resize:vertical;line-height:1.6}\n.gw-err{font-size:13px;color:var(--text-danger);margin-top:4px}\n.gw-btn{padding:9px 16px;border-radius:var(--radius);font:inherit;font-size:14px;font-weight:500;cursor:pointer}\n</style>\n<div style=\"padding:1rem 0\">\n  <form class=\"gw-f\" id=\"gw-kapitel-anlegen\" novalidate style=\"border:0.5px solid var(--border);border-radius:16px;background:var(--surface-1);padding:var(--pad-lg);display:flex;flex-direction:column;gap:var(--gap-md)\">\n    <div style=\"display:flex;align-items:center;gap:var(--gap-sm)\">\n      <i class=\"ti ti-plus\" style=\"font-size:18px;color:var(--text-secondary)\" aria-hidden=\"true\"></i>\n      <span style=\"font-size:16px;font-weight:500\">Neues Kapitel anlegen</span>\n    </div>\n    <div>\n      <label for=\"gw-title\">Titel</label>\n      <input id=\"gw-title\" placeholder=\"Titel des Kapitels\">\n      <div class=\"gw-err\" id=\"gw-title-err\" hidden>Bitte einen Titel eingeben.</div>\n    </div>\n    <div>\n      <label for=\"gw-summary\">Kurzbeschreibung <span class=\"hint\">kurze Zusammenfassung des Kapitels</span></label>\n      <textarea id=\"gw-summary\" rows=\"2\"></textarea>\n    </div>\n    <div>\n      <label for=\"gw-goal\">Ziel des Kapitels <span class=\"hint\">was soll der Leser danach verstanden haben?</span></label>\n      <textarea id=\"gw-goal\" rows=\"2\"></textarea>\n    </div>\n    <div>\n      <label for=\"gw-pos\">Position</label>\n      <select id=\"gw-pos\">\n        {{#POSITIONS}}\n        <option {{POSITION_SELECTED}}>{{POSITION_LABEL}}</option>\n        {{/POSITIONS}}\n      </select>\n    </div>\n    <div style=\"display:flex;justify-content:flex-end;gap:var(--gap-sm);border-top:0.5px solid var(--border);padding-top:var(--pad-md)\">\n      <button type=\"button\" class=\"gw-btn\" id=\"gw-cancel\" style=\"border:0.5px solid var(--border-strong);background:transparent;color:var(--text-primary)\">Abbrechen</button>\n      <button type=\"button\" class=\"gw-btn\" id=\"gw-save\" style=\"border:0.5px solid var(--border-accent);background:var(--bg-accent);color:var(--text-accent)\">Kapitel anlegen</button>\n    </div>\n  </form>\n</div>\n",run:function(){
function gwSend(text,action,data){var p=Object.assign({action:action},data||{});sendPrompt(text+'\n\n```gw\n'+JSON.stringify(p)+'\n```');}
(function(){
  var f=document.getElementById('gw-kapitel-anlegen');
  var $=function(id){return document.getElementById(id);};
  var t=$('gw-title'),e=$('gw-title-err');
  t.addEventListener('input',function(){e.hidden=true;});
  function lock(){f.querySelectorAll('input,textarea,select,button').forEach(function(x){x.disabled=true;});f.style.opacity='0.6';}
  $('gw-save').addEventListener('click',function(){
    if(!t.value.trim()){e.hidden=false;t.focus();return;}
    var v=function(id){return $(id).value.trim()||'(leer)';};
    lock();
    var s=$('gw-pos');
    gwSend('Neues Kapitel anlegen: '+$('gw-title').value.trim(),'chapter.create',{title:$('gw-title').value.trim(),summary:$('gw-summary').value.trim(),goal:$('gw-goal').value.trim(),position:s.selectedIndex,position_label:s.value});
  });
  $('gw-cancel').addEventListener('click',function(){lock();gwSend('Neues Kapitel anlegen abgebrochen','form.cancel',{form:'chapter.create'});});
})();

}};
  T["kapitel-bearbeiten"]={html:"<h2 class=\"sr-only\">Formular zum Bearbeiten von Kapitel {{CHAPTER_NUMBER}}: Titel, Untertitel, Kurzbeschreibung und Ziel.</h2>\n<style>\n.gw-f label{display:block;font-size:13px;font-weight:500;color:var(--text-primary);margin-bottom:4px}\n.gw-f .hint{font-size:12px;color:var(--text-muted);font-weight:400}\n.gw-f input,.gw-f textarea,.gw-f select{width:100%;box-sizing:border-box;padding:9px 12px;border:0.5px solid var(--border-strong);border-radius:var(--radius);background:var(--surface-2);color:var(--text-primary);font:inherit;font-size:14px}\n.gw-f input:focus,.gw-f textarea:focus,.gw-f select:focus{outline:none;border-color:var(--border-accent)}\n.gw-f textarea{resize:vertical;line-height:1.6}\n.gw-err{font-size:13px;color:var(--text-danger);margin-top:4px}\n.gw-btn{padding:9px 16px;border-radius:var(--radius);font:inherit;font-size:14px;font-weight:500;cursor:pointer}\n</style>\n<div style=\"padding:1rem 0\">\n  <form class=\"gw-f\" id=\"gw-kapitel-bearbeiten\" data-chapter=\"{{CHAPTER_ID}}\" data-num=\"{{CHAPTER_NUMBER}}\" novalidate style=\"border:0.5px solid var(--border);border-radius:16px;background:var(--surface-1);padding:var(--pad-lg);display:flex;flex-direction:column;gap:var(--gap-md)\">\n    <div style=\"display:flex;align-items:center;gap:var(--gap-sm)\">\n      <i class=\"ti ti-pencil\" style=\"font-size:18px;color:var(--text-secondary)\" aria-hidden=\"true\"></i>\n      <span style=\"font-size:16px;font-weight:500\">Kapitel {{CHAPTER_NUMBER}} bearbeiten</span>\n    </div>\n    <div>\n      <label for=\"gw-title\">Titel</label>\n      <input id=\"gw-title\" value=\"{{CHAPTER_TITLE}}\" placeholder=\"Titel des Kapitels\">\n      <div class=\"gw-err\" id=\"gw-title-err\" hidden>Bitte einen Titel eingeben.</div>\n    </div>\n    <div>\n      <label for=\"gw-subtitle\">Untertitel <span class=\"hint\">optional</span></label>\n      <input id=\"gw-subtitle\" value=\"{{CHAPTER_SUBTITLE}}\">\n    </div>\n    <div>\n      <label for=\"gw-summary\">Kurzbeschreibung <span class=\"hint\">kurze Zusammenfassung des Kapitels</span></label>\n      <textarea id=\"gw-summary\" rows=\"2\">{{CHAPTER_SUMMARY}}</textarea>\n    </div>\n    <div>\n      <label for=\"gw-goal\">Ziel des Kapitels <span class=\"hint\">was soll der Leser danach verstanden haben?</span></label>\n      <textarea id=\"gw-goal\" rows=\"2\">{{CHAPTER_GOAL}}</textarea>\n    </div>\n    <div style=\"display:flex;justify-content:flex-end;gap:var(--gap-sm);border-top:0.5px solid var(--border);padding-top:var(--pad-md)\">\n      <button type=\"button\" class=\"gw-btn\" id=\"gw-cancel\" style=\"border:0.5px solid var(--border-strong);background:transparent;color:var(--text-primary)\">Abbrechen</button>\n      <button type=\"button\" class=\"gw-btn\" id=\"gw-save\" style=\"border:0.5px solid var(--border-accent);background:var(--bg-accent);color:var(--text-accent)\">Speichern</button>\n    </div>\n  </form>\n</div>\n",run:function(){
function gwSend(text,action,data){var p=Object.assign({action:action},data||{});sendPrompt(text+'\n\n```gw\n'+JSON.stringify(p)+'\n```');}
(function(){
  var f=document.getElementById('gw-kapitel-bearbeiten');
  var $=function(id){return document.getElementById(id);};
  var id=f.dataset.chapter,num=f.dataset.num;
  var title=$('gw-title'),err=$('gw-title-err');
  title.addEventListener('input',function(){err.hidden=true;});
  function lock(){f.querySelectorAll('input,textarea,button').forEach(function(x){x.disabled=true;});f.style.opacity='0.6';}
  $('gw-save').addEventListener('click',function(){
    if(!title.value.trim()){err.hidden=false;title.focus();return;}
    var g=function(k){return $(k).value.trim();};
    var d={chapter_id:id,title:g('gw-title'),subtitle:g('gw-subtitle'),summary:g('gw-summary'),goal:g('gw-goal')};
    lock();
    gwSend('Kapitel '+num+' speichern: '+d.title,'chapter.update',d);
  });
  $('gw-cancel').addEventListener('click',function(){lock();gwSend('Kapitel '+num+' bearbeiten abgebrochen','form.cancel',{form:'chapter.update',chapter_id:id});});
})();

}};
  T["kapitelansicht"]={html:"<h2 class=\"sr-only\">Kapitel {{CHAPTER_NUMBER}} „{{CHAPTER_TITLE}}“ mit allen Abschnitten, ihren offenen Markern, Kosten und Status.</h2>\n<style>\n.gw-sq{width:40px;height:40px;flex:none;border:0.5px solid var(--border);border-radius:12px;background:var(--surface-2);display:flex;align-items:center;justify-content:center;font-size:20px;color:var(--text-secondary);cursor:pointer;padding:0}\n.gw-sq:hover{border-color:var(--border-strong);color:var(--text-primary)}\n.gw-row{display:flex;align-items:center;gap:var(--gap-md);padding:10px 12px;border:0.5px solid var(--border);border-radius:var(--radius);background:var(--surface-2);color:var(--text-primary);cursor:pointer;text-align:left;font:inherit;width:100%}\n.gw-row:hover{border-color:var(--border-strong)}\n.gw-tag{font-size:11px;padding:1px 7px;border-radius:999px;white-space:nowrap;border:0.5px solid var(--border-warning);background:var(--bg-warning);color:var(--text-warning)}\n.gw-tag.med{border-color:var(--border-danger);background:var(--bg-danger);color:var(--text-danger)}\n.gw-tag.recht{border-color:var(--border-accent);background:var(--bg-accent);color:var(--text-accent)}\n.gw-tag.anek{border-color:var(--border);background:var(--surface-1);color:var(--text-secondary)}\n.gw-num{font-size:13px;color:var(--text-muted);min-width:28px;font-variant-numeric:tabular-nums}\n.gw-meta{font-size:12px;color:var(--text-muted)}\n@media (max-width:520px){.gw-tags{display:none!important}}\n</style>\n<div style=\"padding:1rem 0\">\n  <div id=\"gw-kapitel\" data-chapter-id=\"{{CHAPTER_ID}}\" data-chapter-number=\"{{CHAPTER_NUMBER}}\" data-chapter-title=\"{{CHAPTER_TITLE}}\" style=\"border:0.5px solid var(--border);border-radius:16px;background:var(--surface-1);padding:var(--pad-lg);display:flex;flex-direction:column;gap:var(--gap-md)\">\n    <div>\n      <div style=\"display:flex;align-items:flex-start;gap:var(--gap-md);flex-wrap:wrap-reverse\">\n        <div style=\"flex:1;min-width:220px\">\n          <div style=\"display:flex;align-items:center;gap:var(--gap-sm);flex-wrap:wrap;margin-bottom:4px\">\n            <span style=\"font-size:12px;font-weight:500;padding:2px 8px;border-radius:999px;border:0.5px solid var(--border-accent);background:var(--bg-accent);color:var(--text-accent)\">{{PROJECT_TITLE_SHORT}}</span>\n            <span style=\"font-size:12px;color:var(--text-muted)\">Kapitel {{CHAPTER_NUMBER}}</span>\n          </div>\n          <div style=\"font-size:20px;font-weight:500;line-height:1.3\">{{CHAPTER_TITLE}}</div>\n          <div id=\"gw-subtitle\" style=\"font-size:14px;color:var(--text-secondary);font-style:italic;margin-top:2px\">{{CHAPTER_SUBTITLE}}</div>\n        </div>\n        <div style=\"display:flex;gap:var(--gap-sm);margin-left:auto\">\n          <button type=\"button\" class=\"gw-sq\" data-p=\"Zurück zur Projektübersicht\" data-a=\"view.project\" title=\"Zur Projektübersicht\" aria-label=\"Zur Projektübersicht\"><i class=\"ti ti-arrow-left\" aria-hidden=\"true\"></i></button>\n          <button type=\"button\" class=\"gw-sq\" data-p=\"Kapitel {{CHAPTER_NUMBER}} bearbeiten\" data-a=\"chapter.edit.open\" data-args='{\"chapter_id\":\"{{CHAPTER_ID}}\"}' title=\"Kapitel bearbeiten\" aria-label=\"Kapitel bearbeiten\"><i class=\"ti ti-edit\" aria-hidden=\"true\"></i></button>\n          <button type=\"button\" class=\"gw-sq\" data-p=\"Neuen Abschnitt in Kapitel {{CHAPTER_NUMBER}} anlegen\" data-a=\"section.create.open\" data-args='{\"chapter_id\":\"{{CHAPTER_ID}}\"}' title=\"Neuer Abschnitt\" aria-label=\"Neuer Abschnitt\"><i class=\"ti ti-plus\" aria-hidden=\"true\"></i></button>\n          <button type=\"button\" class=\"gw-sq\" data-p=\"Abschnittsreihenfolge in Kapitel {{CHAPTER_NUMBER}} ändern\" data-a=\"section.reorder.open\" data-args='{\"chapter_id\":\"{{CHAPTER_ID}}\"}' title=\"Abschnittsreihenfolge ändern\" aria-label=\"Abschnittsreihenfolge ändern\"><i class=\"ti ti-arrows-sort\" aria-hidden=\"true\"></i></button>\n        </div>\n      </div>\n      <div style=\"display:flex;align-items:center;justify-content:space-between;gap:var(--gap-md);flex-wrap:wrap;margin-top:8px\">\n        <div style=\"font-size:14px;color:var(--text-secondary);display:flex;align-items:center;gap:var(--gap-md);flex-wrap:wrap\">\n          <span style=\"display:flex;align-items:center;gap:6px\"><i class=\"ti ti-list-numbers\" aria-hidden=\"true\"></i>{{SECTION_COUNT_TEXT}}</span>\n          <span style=\"display:flex;align-items:center;gap:6px\"><i class=\"ti ti-alert-triangle\" aria-hidden=\"true\"></i>{{MARKER_COUNT_TEXT}}</span>\n        </div>\n        <div style=\"font-size:14px;color:var(--text-secondary);display:flex;align-items:center;gap:6px;margin-left:auto\" title=\"{{CHAPTER_COST_HINT}}\"><i class=\"ti ti-coins\" aria-hidden=\"true\"></i><span style=\"font-variant-numeric:tabular-nums\">{{CHAPTER_COST}}</span></div>\n      </div>\n    </div>\n    <div style=\"border-top:0.5px solid var(--border);padding-top:var(--pad-md)\">\n      <div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:8px\">\n        <span style=\"font-size:12px;color:var(--text-muted)\">Abschnitte</span>\n        <span style=\"font-size:12px;color:var(--text-muted);display:flex;gap:6px;flex-wrap:wrap\"><span class=\"gw-tag anek\">Anekdote</span><span class=\"gw-tag\">Quelle</span><span class=\"gw-tag med\">Medizin</span><span class=\"gw-tag recht\">Recht</span></span>\n      </div>\n      <div id=\"gw-sections\" style=\"display:flex;flex-direction:column;gap:var(--gap-xs)\">\n        {{#SECTIONS}}\n        <button type=\"button\" class=\"gw-row\" data-id=\"{{SECTION_ID}}\" data-number=\"{{SECTION_NUMBER}}\" data-title=\"{{SECTION_TITLE}}\" data-anekdote=\"{{MARKERS_ANEKDOTE}}\" data-quelle=\"{{MARKERS_QUELLE}}\" data-medizin=\"{{MARKERS_MEDIZIN}}\" data-recht=\"{{MARKERS_RECHT}}\"><span class=\"gw-num\">{{SECTION_NUMBER}}</span><span style=\"flex:1;min-width:0;font-size:14px;font-weight:500\">{{SECTION_TITLE}}</span><span class=\"gw-tags\" style=\"display:flex;gap:4px;flex-wrap:wrap;justify-content:flex-end\"></span><span class=\"gw-meta\" style=\"min-width:32px;text-align:right\" title=\"Kosten\">{{SECTION_COST}}</span><span class=\"gw-meta\">{{SECTION_STATUS}}</span><i class=\"ti ti-chevron-right\" style=\"font-size:16px;color:var(--text-muted)\" aria-hidden=\"true\"></i></button>\n        {{/SECTIONS}}\n      </div>\n    </div>\n    <div style=\"border-top:0.5px solid var(--border);padding-top:var(--pad-md);display:flex;align-items:center;gap:var(--gap-sm);font-size:13px;color:var(--text-secondary)\">\n      <i class=\"ti ti-info-circle\" aria-hidden=\"true\"></i>Kapitelzusammenführung erst möglich, wenn alle Abschnitte freigegeben sind ({{APPROVED_COUNT_TEXT}}).\n    </div>\n  </div>\n</div>\n",run:function(){
function gwSend(text,action,data){var p=Object.assign({action:action},data||{});sendPrompt(text+'\n\n```gw\n'+JSON.stringify(p)+'\n```');}
(function(){
  var wrap=document.getElementById('gw-kapitel');
  var sub=document.getElementById('gw-subtitle');
  if(!sub.textContent.trim())sub.remove();

  var list=document.getElementById('gw-sections');
  var rows=list.querySelectorAll('.gw-row');
  if(!rows.length){
    var p=document.createElement('div');
    p.className='gw-meta';p.style.padding='8px 0';
    p.textContent='Noch keine Abschnitte';
    list.appendChild(p);
  }
  rows.forEach(function(r){
    var n=function(k){return parseInt(r.dataset[k],10)||0;};
    var box=r.querySelector('.gw-tags'),add=function(cls,label,c){
      if(!c)return;
      var s=document.createElement('span');s.className='gw-tag'+(cls?' '+cls:'');
      s.textContent=label+(c>1?' ×'+c:'');box.appendChild(s);
    };
    add('anek','Anekdote',n('anekdote'));
    add('','Quelle',n('quelle'));
    add('med','Medizin',n('medizin'));
    add('recht','Recht',n('recht'));
    if(!box.children.length){
      box.innerHTML='<span class="gw-meta" style="display:flex;align-items:center;gap:4px"><i class="ti ti-check" aria-hidden="true"></i>keine Marker</span>';
    }
    r.addEventListener('click',function(){gwSend('Abschnitt '+r.dataset.number+' „'+r.dataset.title+'“ bearbeiten','view.section',{section_id:r.dataset.id});});
  });

  wrap.querySelectorAll('.gw-sq[data-p]').forEach(function(b){b.addEventListener('click',function(){gwSend(b.dataset.p,b.dataset.a,b.dataset.args?JSON.parse(b.dataset.args):{});});});
})();

}};
  T["projektdaten-bearbeiten"]={html:"<h2 class=\"sr-only\">Formular zum Bearbeiten der Projektdaten: Titel, Kurztitel, Autor, Kurzbeschreibung und Beschreibung.</h2>\n<style>\n.gw-f label{display:block;font-size:13px;font-weight:500;color:var(--text-primary);margin-bottom:4px}\n.gw-f .hint{font-size:12px;color:var(--text-muted);font-weight:400}\n.gw-f input,.gw-f textarea{width:100%;box-sizing:border-box;padding:9px 12px;border:0.5px solid var(--border-strong);border-radius:var(--radius);background:var(--surface-2);color:var(--text-primary);font:inherit;font-size:14px}\n.gw-f input:focus,.gw-f textarea:focus{outline:none;border-color:var(--border-accent)}\n.gw-f textarea{resize:vertical;line-height:1.6}\n.gw-err{font-size:13px;color:var(--text-danger);margin-top:4px}\n.gw-btn{padding:9px 16px;border-radius:var(--radius);font:inherit;font-size:14px;font-weight:500;cursor:pointer}\n</style>\n<div style=\"padding:1rem 0\">\n  <form class=\"gw-f\" id=\"gw-projektdaten\" novalidate style=\"border:0.5px solid var(--border);border-radius:16px;background:var(--surface-1);padding:var(--pad-lg);display:flex;flex-direction:column;gap:var(--gap-md)\">\n    <div style=\"display:flex;align-items:center;gap:var(--gap-sm)\">\n      <i class=\"ti ti-edit\" style=\"font-size:18px;color:var(--text-secondary)\" aria-hidden=\"true\"></i>\n      <span style=\"font-size:16px;font-weight:500\">Projektdaten bearbeiten</span>\n    </div>\n    <div>\n      <label for=\"gw-title\">Titel</label>\n      <input id=\"gw-title\" value=\"{{PROJECT_TITLE}}\" placeholder=\"Titel des Buches\">\n      <div class=\"gw-err\" id=\"gw-title-err\" hidden>Bitte einen Titel eingeben.</div>\n    </div>\n    <div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:var(--gap-md)\">\n      <div>\n        <label for=\"gw-short\">Kurztitel <span class=\"hint\">für Badge und Listen</span></label>\n        <input id=\"gw-short\" maxlength=\"40\" value=\"{{PROJECT_TITLE_SHORT}}\">\n      </div>\n      <div>\n        <label for=\"gw-author\">Autor</label>\n        <input id=\"gw-author\" value=\"{{PROJECT_AUTHOR}}\" placeholder=\"Name des Autors\">\n      </div>\n    </div>\n    <div>\n      <label for=\"gw-dshort\">Kurzbeschreibung <span class=\"hint\">ein Satz</span></label>\n      <input id=\"gw-dshort\" value=\"{{PROJECT_DESCRIPTION_SHORT}}\">\n    </div>\n    <div>\n      <label for=\"gw-desc\">Beschreibung</label>\n      <textarea id=\"gw-desc\" rows=\"5\">{{PROJECT_DESCRIPTION}}</textarea>\n    </div>\n    <div style=\"display:flex;justify-content:flex-end;gap:var(--gap-sm);border-top:0.5px solid var(--border);padding-top:var(--pad-md)\">\n      <button type=\"button\" class=\"gw-btn\" id=\"gw-cancel\" style=\"border:0.5px solid var(--border-strong);background:transparent;color:var(--text-primary)\">Abbrechen</button>\n      <button type=\"button\" class=\"gw-btn\" id=\"gw-save\" style=\"border:0.5px solid var(--border-accent);background:var(--bg-accent);color:var(--text-accent)\">Speichern</button>\n    </div>\n  </form>\n</div>\n",run:function(){
function gwSend(text,action,data){var p=Object.assign({action:action},data||{});sendPrompt(text+'\n\n```gw\n'+JSON.stringify(p)+'\n```');}
(function(){
  var f=document.getElementById('gw-projektdaten');
  var $=function(id){return document.getElementById(id);};
  var t=$('gw-title'),e=$('gw-title-err');
  t.addEventListener('input',function(){e.hidden=true;});
  function lock(){f.querySelectorAll('input,textarea,button').forEach(function(x){x.disabled=true;});f.style.opacity='0.6';}
  $('gw-save').addEventListener('click',function(){
    if(!t.value.trim()){e.hidden=false;t.focus();return;}
    var g=function(id){return $(id).value.trim();};
    var d={title:g('gw-title'),title_short:g('gw-short'),author:g('gw-author'),description_short:g('gw-dshort'),description:g('gw-desc')};
    lock();
    gwSend('Projektdaten speichern: '+d.title,'project.update',d);
  });
  $('gw-cancel').addEventListener('click',function(){lock();gwSend('Projektdaten bearbeiten abgebrochen','form.cancel',{form:'project.update'});});
})();

}};
  T["projekteinstellungen"]={html:"<h2 class=\"sr-only\">Formular für die Projekteinstellungen: feste Regeln, Faktencheck-Vorgabe und Buchsatz.</h2>\n<style>\n.gw-f label{display:block;font-size:13px;font-weight:500;color:var(--text-primary);margin-bottom:4px}\n.gw-f .hint{font-size:12px;color:var(--text-muted);font-weight:400}\n.gw-f select{width:100%;box-sizing:border-box;padding:9px 12px;border:0.5px solid var(--border-strong);border-radius:var(--radius);background:var(--surface-2);color:var(--text-primary);font:inherit;font-size:14px}\n.gw-f select:focus{outline:none;border-color:var(--border-accent)}\n.gw-f .chk{display:flex;align-items:center;gap:8px;font-size:14px;font-weight:400;margin:0;cursor:pointer}\n.gw-f .chk input{width:16px;height:16px;margin:0;accent-color:var(--text-accent)}\n.gw-sec{font-size:12px;color:var(--text-muted);text-transform:uppercase;letter-spacing:0.04em;margin-bottom:8px}\n.gw-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:var(--gap-md)}\n.gw-fx{display:grid;grid-template-columns:auto 1fr;gap:4px 16px;font-size:13px}\n.gw-fx dt{color:var(--text-secondary)}\n.gw-fx dd{margin:0;color:var(--text-primary)}\n.gw-btn{padding:9px 16px;border-radius:var(--radius);font:inherit;font-size:14px;font-weight:500;cursor:pointer}\n.gw-btn:disabled{opacity:0.4;cursor:default}\n</style>\n<div style=\"padding:1rem 0\">\n  <form class=\"gw-f\" id=\"gw-einstellungen\" novalidate\n    data-fc=\"{{FACT_CHECK_DEFAULT}}\" data-page=\"{{PAGE_SIZE}}\" data-font=\"{{FONT}}\" data-size=\"{{FONT_SIZE}}\"\n    data-title=\"{{TITLE_PAGE}}\" data-imprint=\"{{IMPRINT}}\" data-toc=\"{{TOC}}\" data-depth=\"{{TOC_DEPTH}}\"\n    style=\"border:0.5px solid var(--border);border-radius:16px;background:var(--surface-1);padding:var(--pad-lg);display:flex;flex-direction:column;gap:var(--gap-lg)\">\n    <div style=\"display:flex;align-items:center;gap:var(--gap-sm)\">\n      <i class=\"ti ti-settings\" style=\"font-size:18px;color:var(--text-secondary)\" aria-hidden=\"true\"></i>\n      <span style=\"font-size:16px;font-weight:500\">Projekteinstellungen</span>\n    </div>\n\n    <div>\n      <div class=\"gw-sec\">Feste Regeln</div>\n      <dl class=\"gw-fx\" style=\"margin:0\">\n        {{#FIXED}}\n        <dt>{{FIXED_LABEL}}</dt><dd>{{FIXED_VALUE}}</dd>\n        {{/FIXED}}\n      </dl>\n      <div style=\"font-size:12px;color:var(--text-muted);margin-top:8px\"><i class=\"ti ti-lock\" aria-hidden=\"true\"></i> Nicht hier änderbar. Abschwächen nur im Chat mit ausdrücklicher Bestätigung.</div>\n    </div>\n\n    <div style=\"border-top:0.5px solid var(--border);padding-top:var(--pad-md)\">\n      <div class=\"gw-sec\">Arbeitsweise</div>\n      <div class=\"gw-grid\">\n        <div>\n          <label for=\"gw-fc\">Faktencheck für neue Abschnitte</label>\n          <select id=\"gw-fc\">\n            <option value=\"disabled\">aus</option>\n            <option value=\"optional\">optional</option>\n            <option value=\"requested\">angefordert</option>\n          </select>\n        </div>\n      </div>\n    </div>\n\n    <div style=\"border-top:0.5px solid var(--border);padding-top:var(--pad-md)\">\n      <div class=\"gw-sec\">Buchsatz <span style=\"text-transform:none;letter-spacing:0\">· gilt für PDF, DOCX und EPUB der nächsten Auflage</span></div>\n      <div class=\"gw-grid\">\n        <div>\n          <label for=\"gw-page\">Seitenformat</label>\n          <select id=\"gw-page\">\n            <option value=\"a5\">A5 (14,8 × 21 cm)</option>\n            <option value=\"12x19\">12 × 19 cm</option>\n            <option value=\"13.5x21.5\">13,5 × 21,5 cm</option>\n            <option value=\"a4\">A4 (21 × 29,7 cm)</option>\n          </select>\n        </div>\n        <div>\n          <label for=\"gw-font\">Schrift</label>\n          <select id=\"gw-font\">\n            <option value=\"serif\">Serifenschrift</option>\n            <option value=\"sans\">Serifenlose Schrift</option>\n          </select>\n        </div>\n        <div>\n          <label for=\"gw-size\">Schriftgröße</label>\n          <select id=\"gw-size\">\n            <option value=\"10\">10 pt</option>\n            <option value=\"10.5\">10,5 pt</option>\n            <option value=\"11\">11 pt</option>\n            <option value=\"11.5\">11,5 pt</option>\n            <option value=\"12\">12 pt</option>\n          </select>\n        </div>\n      </div>\n      <div class=\"gw-grid\" style=\"margin-top:var(--gap-md);align-items:end\">\n        <div>\n          <div style=\"font-size:13px;font-weight:500;margin-bottom:6px\">Titelei</div>\n          <label class=\"chk\"><input type=\"checkbox\" id=\"gw-title\"> Titelseite</label>\n          <label class=\"chk\" style=\"margin-top:6px\"><input type=\"checkbox\" id=\"gw-imprint\"> Impressum</label>\n        </div>\n        <div>\n          <div style=\"font-size:13px;font-weight:500;margin-bottom:6px\">Inhaltsverzeichnis</div>\n          <label class=\"chk\"><input type=\"checkbox\" id=\"gw-toc\"> anzeigen</label>\n        </div>\n        <div>\n          <label for=\"gw-depth\">Tiefe <span class=\"hint\">des Inhaltsverzeichnisses</span></label>\n          <select id=\"gw-depth\">\n            <option value=\"1\">nur Kapitel</option>\n            <option value=\"2\">Kapitel und Abschnitte</option>\n          </select>\n        </div>\n      </div>\n    </div>\n\n    <div style=\"display:flex;justify-content:flex-end;gap:var(--gap-sm);border-top:0.5px solid var(--border);padding-top:var(--pad-md)\">\n      <button type=\"button\" class=\"gw-btn\" id=\"gw-cancel\" style=\"border:0.5px solid var(--border-strong);background:transparent;color:var(--text-primary)\">Abbrechen</button>\n      <button type=\"button\" class=\"gw-btn\" id=\"gw-save\" style=\"border:0.5px solid var(--border-accent);background:var(--bg-accent);color:var(--text-accent)\" disabled>Speichern</button>\n    </div>\n  </form>\n</div>\n",run:function(){
function gwSend(text,action,data){var p=Object.assign({action:action},data||{});sendPrompt(text+'\n\n```gw\n'+JSON.stringify(p)+'\n```');}
(function(){
  var f=document.getElementById('gw-einstellungen'),ds=f.dataset;
  var $=function(id){return document.getElementById(id);};
  function set(id,v){if(v)$(id).value=v;}
  set('gw-fc',ds.fc);set('gw-page',ds.page);set('gw-font',ds.font);set('gw-size',ds.size);set('gw-depth',ds.depth);
  $('gw-title').checked=ds.title==='true';$('gw-imprint').checked=ds.imprint==='true';$('gw-toc').checked=ds.toc==='true';
  function data(){return {fact_checking_default:$('gw-fc').value,typesetting:{page_size:$('gw-page').value,font:$('gw-font').value,font_size:+$('gw-size').value,title_page:$('gw-title').checked,imprint:$('gw-imprint').checked,toc:$('gw-toc').checked,toc_depth:+$('gw-depth').value}};}
  var start=JSON.stringify(data()),done=false;
  function refresh(){$('gw-depth').disabled=done||!$('gw-toc').checked;$('gw-save').disabled=done||JSON.stringify(data())===start;}
  f.addEventListener('change',refresh);
  function lock(){done=true;f.querySelectorAll('input,select,button').forEach(function(x){x.disabled=true;});f.style.opacity='0.6';}
  $('gw-save').addEventListener('click',function(){
    var d=data();
    lock();
    gwSend('Projekteinstellungen speichern','project.settings.update',d);
  });
  $('gw-cancel').addEventListener('click',function(){lock();gwSend('Projekteinstellungen abgebrochen','form.cancel',{form:'project.settings.update'});});
  refresh();
})();

}};
  T["projektuebersicht"]={html:"<h2 class=\"sr-only\">Projektübersicht für „{{PROJECT_TITLE}}“ von {{PROJECT_AUTHOR}} mit bisherigen Kosten und Links zu den Kapiteln.</h2>\n<style>\n.gw-ch{display:flex;align-items:center;gap:var(--gap-md);padding:10px 12px;border:0.5px solid var(--border);border-radius:var(--radius);background:var(--surface-2);color:var(--text-primary);text-decoration:none}\n.gw-ch:hover{border-color:var(--border-strong)}\n.gw-sq{width:40px;height:40px;flex:none;border:0.5px solid var(--border);border-radius:12px;background:var(--surface-2);display:flex;align-items:center;justify-content:center;font-size:20px;color:var(--text-secondary);cursor:pointer;padding:0}\n.gw-sq:hover{border-color:var(--border-strong);color:var(--text-primary)}\n.gw-cost{font-size:13px;color:var(--text-secondary);font-variant-numeric:tabular-nums;min-width:64px;text-align:right}\n</style>\n<div style=\"padding:1rem 0\">\n  <div style=\"border:0.5px solid var(--border);border-radius:16px;background:var(--surface-1);padding:var(--pad-lg);display:flex;flex-direction:column;gap:var(--gap-md)\">\n    <div>\n      <div style=\"display:flex;align-items:flex-start;gap:var(--gap-md);flex-wrap:wrap-reverse\">\n        <div style=\"flex:1;min-width:220px\">\n          <div style=\"display:flex;align-items:center;gap:var(--gap-sm);flex-wrap:wrap;margin-bottom:4px\">\n            <span style=\"font-size:12px;font-weight:500;padding:2px 8px;border-radius:999px;border:0.5px solid var(--border-accent);background:var(--bg-accent);color:var(--text-accent)\">{{PROJECT_TITLE_SHORT}}</span>\n            <span style=\"font-size:12px;color:var(--text-muted)\">Buchprojekt · {{PROJECT_EDITION_TEXT}}</span>\n          </div>\n          <div style=\"font-size:20px;font-weight:500;line-height:1.3;color:var(--text-primary)\">{{PROJECT_TITLE}}</div>\n        </div>\n        <div style=\"display:flex;gap:var(--gap-sm);margin-left:auto\">\n          <button type=\"button\" class=\"gw-sq\" data-p=\"Projektdaten bearbeiten\" data-a=\"project.edit\" title=\"Projektdaten bearbeiten\" aria-label=\"Projektdaten bearbeiten\"><i class=\"ti ti-edit\" aria-hidden=\"true\"></i></button>\n          <button type=\"button\" class=\"gw-sq\" data-p=\"Neues Kapitel anlegen\" data-a=\"chapter.create.open\" title=\"Neues Kapitel anlegen\" aria-label=\"Neues Kapitel anlegen\"><i class=\"ti ti-plus\" aria-hidden=\"true\"></i></button>\n          <button type=\"button\" class=\"gw-sq\" data-p=\"Kapitelreihenfolge ändern\" data-a=\"chapter.reorder.open\" title=\"Kapitelreihenfolge ändern\" aria-label=\"Kapitelreihenfolge ändern\"><i class=\"ti ti-arrows-sort\" aria-hidden=\"true\"></i></button>\n          <button type=\"button\" class=\"gw-sq\" data-p=\"Neue Auflage erzeugen\" data-a=\"edition.create.open\" title=\"Neue Auflage erzeugen\" aria-label=\"Neue Auflage erzeugen\"><i class=\"ti ti-books\" aria-hidden=\"true\"></i></button>\n          <button type=\"button\" class=\"gw-sq\" data-p=\"Projekteinstellungen anzeigen\" data-a=\"project.settings.open\" title=\"Projekteinstellungen\" aria-label=\"Projekteinstellungen\"><i class=\"ti ti-settings\" aria-hidden=\"true\"></i></button>\n        </div>\n      </div>\n      <div style=\"display:flex;align-items:center;justify-content:space-between;gap:var(--gap-md);flex-wrap:wrap;margin-top:6px\">\n        <div style=\"font-size:14px;color:var(--text-secondary);display:flex;align-items:center;gap:6px\"><i class=\"ti ti-user\" aria-hidden=\"true\"></i>{{PROJECT_AUTHOR}}</div>\n        <div style=\"font-size:14px;color:var(--text-secondary);display:flex;align-items:center;gap:6px;margin-left:auto\" title=\"{{PROJECT_COST_HINT}}\"><i class=\"ti ti-coins\" aria-hidden=\"true\"></i><span style=\"font-variant-numeric:tabular-nums\">{{PROJECT_COST}}</span></div>\n      </div>\n    </div>\n    <p style=\"margin:0;font-size:15px;line-height:1.6;color:var(--text-primary);border-left:2px solid var(--border-accent);border-radius:0;padding-left:var(--pad-md)\">{{PROJECT_DESCRIPTION_SHORT}}</p>\n    <div style=\"border-top:0.5px solid var(--border);padding-top:var(--pad-md)\">\n      <div style=\"font-size:12px;color:var(--text-muted);margin-bottom:4px\">Beschreibung</div>\n      <p style=\"margin:0;font-size:14px;line-height:1.7;color:var(--text-secondary)\">{{PROJECT_DESCRIPTION}}</p>\n    </div>\n    <div data-gw-if=\"CHAPTERS\" style=\"border-top:0.5px solid var(--border);padding-top:var(--pad-md)\">\n      <div style=\"font-size:12px;color:var(--text-muted);margin-bottom:8px\">Kapitel</div>\n      <div style=\"display:flex;flex-direction:column;gap:var(--gap-xs)\">\n        {{#CHAPTERS}}\n        <a class=\"gw-ch\" href=\"{{CHAPTER_URL}}\"><span style=\"font-size:13px;color:var(--text-muted);min-width:20px\">{{CHAPTER_NUMBER}}</span><span style=\"flex:1;font-size:14px;font-weight:500\">{{CHAPTER_TITLE}}</span><span class=\"gw-cost\" title=\"{{CHAPTER_COST_HINT}}\">{{CHAPTER_COST}}</span><span style=\"font-size:12px;color:var(--text-muted)\">{{CHAPTER_STATUS}}</span><i class=\"ti ti-external-link\" style=\"font-size:16px;color:var(--text-muted)\" aria-hidden=\"true\"></i></a>\n        {{/CHAPTERS}}\n      </div>\n    </div>\n  </div>\n</div>\n",run:function(){
function gwSend(text,action,data){var p=Object.assign({action:action},data||{});sendPrompt(text+'\n\n```gw\n'+JSON.stringify(p)+'\n```');}
document.querySelectorAll('.gw-sq[data-p]').forEach(function(b){b.addEventListener('click',function(){gwSend(b.dataset.p,b.dataset.a,b.dataset.args?JSON.parse(b.dataset.args):{});});});

}};
  T["reihenfolge"]={html:"<h2 class=\"sr-only\">{{REORDER_HEADING}}: Einträge mit den Pfeilen verschieben und speichern.</h2>\n<style>\n.gw-btn{padding:9px 16px;border-radius:var(--radius);font:inherit;font-size:14px;font-weight:500;cursor:pointer}\n.gw-btn:disabled{opacity:0.4;cursor:default}\n.gw-row{display:flex;align-items:center;gap:var(--gap-sm);padding:8px 10px;border:0.5px solid var(--border);border-radius:var(--radius);background:var(--surface-2)}\n.gw-row.moved{border-color:var(--border-accent)}\n.gw-num{min-width:2.6em;font-size:13px;color:var(--text-muted);font-variant-numeric:tabular-nums}\n.gw-t{flex:1;font-size:14px;min-width:0}\n.gw-mv{width:30px;height:30px;display:inline-flex;align-items:center;justify-content:center;border:0.5px solid var(--border);border-radius:var(--radius);background:transparent;color:var(--text-secondary);cursor:pointer;padding:0}\n.gw-mv:hover:not(:disabled){border-color:var(--border-strong);color:var(--text-primary)}\n.gw-mv:disabled{opacity:0.3;cursor:default}\n</style>\n<div style=\"padding:1rem 0\">\n  <div id=\"gw-reihenfolge\" data-kind=\"{{REORDER_KIND}}\" data-chapter=\"{{CHAPTER_ID}}\" data-num=\"{{CHAPTER_NUMBER}}\" style=\"border:0.5px solid var(--border);border-radius:16px;background:var(--surface-1);padding:var(--pad-lg);display:flex;flex-direction:column;gap:var(--gap-md)\">\n    <div style=\"display:flex;align-items:center;gap:var(--gap-sm)\">\n      <i class=\"ti ti-arrows-sort\" style=\"font-size:18px;color:var(--text-secondary)\" aria-hidden=\"true\"></i>\n      <span style=\"font-size:16px;font-weight:500\">{{REORDER_HEADING}}</span>\n    </div>\n    <div id=\"gw-list\" style=\"display:flex;flex-direction:column;gap:6px\">\n      {{#ITEMS}}\n      <div class=\"gw-row\" data-id=\"{{ITEM_ID}}\" data-num=\"{{ITEM_NUMBER}}\">\n        <span class=\"gw-num\">{{ITEM_NUMBER}}</span>\n        <span class=\"gw-t\">{{ITEM_TITLE}}</span>\n        <button type=\"button\" class=\"gw-mv\" data-d=\"-1\" title=\"Nach oben\" aria-label=\"Nach oben\"><i class=\"ti ti-chevron-up\" aria-hidden=\"true\"></i></button>\n        <button type=\"button\" class=\"gw-mv\" data-d=\"1\" title=\"Nach unten\" aria-label=\"Nach unten\"><i class=\"ti ti-chevron-down\" aria-hidden=\"true\"></i></button>\n      </div>\n      {{/ITEMS}}\n    </div>\n    <div style=\"display:flex;align-items:center;gap:var(--gap-sm);border-top:0.5px solid var(--border);padding-top:var(--pad-md)\">\n      <button type=\"button\" class=\"gw-btn\" id=\"gw-reset\" style=\"border:none;background:transparent;color:var(--text-secondary);padding-left:0\" disabled>Zurücksetzen</button>\n      <span style=\"flex:1\"></span>\n      <button type=\"button\" class=\"gw-btn\" id=\"gw-cancel\" style=\"border:0.5px solid var(--border-strong);background:transparent;color:var(--text-primary)\">Abbrechen</button>\n      <button type=\"button\" class=\"gw-btn\" id=\"gw-save\" style=\"border:0.5px solid var(--border-accent);background:var(--bg-accent);color:var(--text-accent)\" disabled>Reihenfolge speichern</button>\n    </div>\n  </div>\n</div>\n",run:function(){
function gwSend(text,action,data){var p=Object.assign({action:action},data||{});sendPrompt(text+'\n\n```gw\n'+JSON.stringify(p)+'\n```');}
(function(){
  var w=document.getElementById('gw-reihenfolge'),list=document.getElementById('gw-list');
  var kind=w.dataset.kind,ch=w.dataset.chapter,num=w.dataset.num;
  var rows=function(){return Array.prototype.slice.call(list.querySelectorAll('.gw-row'));};
  var orig=rows().map(function(r){return r.dataset.id;});
  var done=false;
  function order(){return rows().map(function(r){return r.dataset.id;});}
  function refresh(){
    var rs=rows(),changed=false;
    rs.forEach(function(r,i){
      var moved=orig[i]!==r.dataset.id;changed=changed||moved;
      r.classList.toggle('moved',moved);
      var b=r.querySelectorAll('.gw-mv');b[0].disabled=done||i===0;b[1].disabled=done||i===rs.length-1;
    });
    document.getElementById('gw-save').disabled=done||!changed;
    document.getElementById('gw-reset').disabled=done||!changed;
  }
  list.addEventListener('click',function(ev){
    var b=ev.target.closest('.gw-mv');if(!b||b.disabled)return;
    var r=b.closest('.gw-row'),d=+b.dataset.d;
    if(d<0&&r.previousElementSibling)list.insertBefore(r,r.previousElementSibling);
    if(d>0&&r.nextElementSibling)list.insertBefore(r.nextElementSibling,r);
    refresh();
  });
  document.getElementById('gw-reset').addEventListener('click',function(){
    orig.forEach(function(id){list.appendChild(list.querySelector('[data-id="'+id+'"]'));});refresh();
  });
  function lock(){done=true;refresh();w.querySelectorAll('button').forEach(function(x){x.disabled=true;});w.style.opacity='0.6';}
  document.getElementById('gw-save').addEventListener('click',function(){
    var o=order(),nums=rows().map(function(r){return r.dataset.num;}).join(', ');
    lock();
    if(kind==='section')gwSend('Abschnittsreihenfolge in Kapitel '+num+' speichern: '+nums,'section.reorder',{chapter_id:ch,order:o});
    else gwSend('Kapitelreihenfolge speichern: '+nums,'chapter.reorder',{order:o});
  });
  document.getElementById('gw-cancel').addEventListener('click',function(){
    lock();
    if(kind==='section')gwSend('Abschnittsreihenfolge in Kapitel '+num+' abgebrochen','form.cancel',{form:'section.reorder',chapter_id:ch});
    else gwSend('Kapitelreihenfolge abgebrochen','form.cancel',{form:'chapter.reorder'});
  });
  refresh();
})();

}};

  function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
  function fillText(t,d){return t.replace(/\{\{([A-Z_]+)\}\}/g,function(m,k){return Object.prototype.hasOwnProperty.call(d,k)?esc(d[k]):m;});}
  function fill(t,d){
    t=t.replace(/\{\{#([A-Z_]+)\}\}\n?([\s\S]*?)[ \t]*\{\{\/\1\}\}\n?/g,function(m,k,body){
      var rows=d[k]||[];return rows.map(function(r){return fillText(body,r);}).join('');
    });
    return fillText(t,d);
  }
  function render(name,data,el){
    var t=T[name];
    if(!t)throw new Error('GhostWriter-Vorlage unbekannt: '+name);
    el=el||document.getElementById('gw');
    data=data||{};
    el.innerHTML=fill(t.html,data);
    el.querySelectorAll('[data-gw-if]').forEach(function(n){
      var v=data[n.getAttribute('data-gw-if')];
      if(!v||(Array.isArray(v)&&!v.length))n.remove();
    });
    t.run();
  }
  window.GW={version:VERSION,templates:Object.keys(T),render:render};

})();
